<style>
@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');
:root{--nt-dark:#302e27;--nt-gold:#dbae56;--nt-paper:#f7f4ee;--nt-ink:#34322d;--nt-muted:#817c73;--nt-serif:'Playfair Display',Georgia,serif;--nt-sans:Manrope,Arial,sans-serif}.nt-page{font-family:var(--nt-sans);color:var(--nt-ink);background:#fff}.nt-container{width:min(1280px,calc(100% - 48px));margin:auto}.foot-header{background:var(--nt-dark);color:#fff}.foot-header__masthead{padding:20px 0}.foot-header__masthead-inner{display:flex;justify-content:space-between;align-items:center;gap:20px}.foot-brand{display:flex;align-items:center;gap:11px;color:#fff;text-decoration:none}.foot-brand img{max-width:200px;max-height:60px}.foot-brand__monogram{display:grid;place-items:center;width:45px;height:45px;border:1px solid var(--nt-gold);color:var(--nt-gold);font:700 25px var(--nt-serif)}.foot-brand strong{display:block;font:700 18px var(--nt-serif)}.foot-brand small{display:block;color:#c6c0b4;font-size:10px}.foot-header__account{display:flex;gap:9px;align-items:center}.foot-header__account button,.foot-header__account a{border:0;background:none;color:#fff;font:600 13px var(--nt-sans);cursor:pointer;text-decoration:none}.foot-header__account button:hover{color:var(--nt-gold)}.foot-navigation-wrap{background:#fff}.foot-navigation{min-height:72px;display:flex;align-items:center;justify-content:center;gap:16px}.foot-navigation a{padding:24px 10px;color:var(--nt-ink);font:700 14px var(--nt-serif);text-decoration:none}.foot-navigation a:hover{color:var(--nt-gold)}.foot-mobile-toggle{display:none}.nt-hero{background:var(--nt-dark)}.nt-hero__slide{display:none;min-height:660px;position:relative;color:#fff}.nt-hero__slide.is-active{display:block}.nt-hero__slide>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.nt-hero__shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(255,255,255,.88),rgba(255,255,255,.32) 55%,rgba(34,32,28,.08))}.nt-hero__content{position:relative;min-height:660px;display:flex;justify-content:center;align-items:flex-start;flex-direction:column;max-width:1280px}.nt-hero__content p,.nt-eyebrow{margin:0 0 14px;color:#a39d91;font:600 16px var(--nt-serif)}.nt-hero__content h1{max-width:700px;margin:0;color:var(--nt-dark);font:700 clamp(43px,5vw,76px)/1.12 var(--nt-serif)}.nt-hero__content div{max-width:560px;margin:18px 0 28px;color:#4c4942;line-height:1.75}.nt-button{display:inline-flex;justify-content:center;align-items:center;padding:15px 30px;border:0;border-radius:30px;background:var(--nt-gold);color:#fff;font:700 14px var(--nt-serif);text-decoration:none}.nt-section{padding:92px 0}.nt-about__grid{display:grid;grid-template-columns:1fr 1fr;gap:85px;align-items:center}.nt-about h2,.nt-section-head h2{margin:0;color:var(--nt-dark);font:700 clamp(34px,4vw,54px)/1.2 var(--nt-serif)}.nt-about__copy>div{margin-top:32px;color:#625d55;line-height:1.8}.nt-text-link{display:inline-block;margin-top:26px;color:var(--nt-gold);font-weight:700;text-decoration:none}.nt-about__media{position:relative}.nt-about__media img{width:100%;height:520px;object-fit:cover;clip-path:polygon(0 0,100% 0,100% 82%,62% 100%,0 88%)}.nt-about__media span{position:absolute;left:-42px;top:48px;padding:23px;background:#fff;color:var(--nt-dark);font:700 44px var(--nt-serif);box-shadow:0 10px 24px rgba(0,0,0,.08)}.nt-about__media small{display:block;color:var(--nt-gold);font:600 11px var(--nt-sans);text-transform:uppercase}.nt-showcase{background:var(--nt-paper)}.nt-section-head{text-align:center;margin-bottom:42px}.nt-section-head--row{display:flex;justify-content:space-between;align-items:end;text-align:left}.nt-showcase__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.nt-showcase__card{position:relative;min-height:380px;overflow:hidden;border-radius:8px}.nt-showcase__card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.nt-showcase__card a{position:absolute;right:22px;bottom:0;left:22px;padding:20px;background:#fff;color:var(--nt-dark);text-align:center;text-decoration:none}.nt-showcase__card h3{margin:0 0 7px;font:700 25px var(--nt-serif)}.nt-showcase__card span{color:var(--nt-muted);font-size:13px}.nt-hours{display:flex;min-height:380px;padding:42px;flex-direction:column;justify-content:center;border-radius:8px;background:linear-gradient(rgba(42,38,29,.77),rgba(42,38,29,.77)),url('https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=900&q=85') center/cover;color:#fff;text-align:center}.nt-hours p{color:var(--nt-gold);font-family:var(--nt-serif)}.nt-hours h3{margin:4px 0 18px;font:700 31px var(--nt-serif)}.nt-hours strong{line-height:1.8}.nt-hours .nt-button{margin-top:26px}.nt-projects{background:#fff}.nt-rail{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(280px,calc((100% - 72px)/4));gap:24px;overflow-x:auto;padding-bottom:18px}.nt-project-card{min-height:400px;position:relative;overflow:hidden;border-radius:8px}.nt-project-card img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}.nt-project-card a{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:end;padding:28px;color:#fff;text-decoration:none;background:linear-gradient(transparent 45%,rgba(24,22,18,.7))}.nt-project-card span{font-size:12px;color:#f3ce8e}.nt-project-card h3{margin:7px 0 0;font:700 25px var(--nt-serif)}.nt-services{background:var(--nt-paper)}.nt-service-grid,.nt-blog__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.nt-service-card{background:#fff}.nt-service-card>img{width:100%;height:245px;object-fit:cover}.nt-service-card>div{padding:24px}.nt-service-card h3,.nt-blog h3{margin:0 0 12px;font:700 26px/1.2 var(--nt-serif)}.nt-service-card p,.nt-blog p{color:var(--nt-muted);font-size:14px;line-height:1.7}.nt-service-card a{color:var(--nt-gold);font-size:13px;font-weight:700;text-decoration:none}.nt-testimonial{display:grid;grid-template-columns:1fr 1fr;min-height:510px;background:var(--nt-dark);color:#fff}.nt-testimonial__copy{display:grid;place-items:center;padding:70px}.nt-testimonial__copy>div{width:min(520px,100%)}.nt-testimonial h2{margin:0;font:700 clamp(34px,4vw,52px)/1.18 var(--nt-serif)}.nt-testimonial blockquote{margin:36px 0 24px;color:#ebe7df;font:600 20px/1.7 var(--nt-serif)}.nt-testimonial small{display:block;margin-top:5px;color:var(--nt-gold)}.nt-testimonial__media img{width:100%;height:100%;object-fit:cover}.nt-blog{background:#fff}.nt-blog article{overflow:hidden;background:var(--nt-paper);border-radius:8px}.nt-blog a{color:inherit;text-decoration:none}.nt-blog img{display:block;width:100%;height:245px;object-fit:cover}.nt-blog article div{padding:22px 25px}.nt-blog small{color:var(--nt-gold);font-size:12px}.nt-partners{padding-top:65px;padding-bottom:65px;text-align:center}.nt-partners>div>div{display:flex;justify-content:space-around;align-items:center;gap:28px;flex-wrap:wrap}.nt-partners a,.nt-partners span{display:grid;place-items:center;min-width:155px;height:76px;color:#726d64;font:700 17px var(--nt-serif)}.nt-partners img{max-width:150px;max-height:65px;filter:grayscale(1);object-fit:contain}.nt-stats{padding-top:0}.nt-stats .nt-container>div{display:grid;grid-template-columns:repeat(3,1fr);padding:55px;border-radius:8px;background:#343129;color:#fff}.nt-stats article{text-align:center}.nt-stats strong{display:block;font:700 56px var(--nt-serif)}.nt-stats span{color:#ded7ca}.foot-footer{background:var(--nt-dark);color:#eee}.foot-footer__top,.foot-footer__grid{width:min(1280px,calc(100% - 48px));margin:auto}.foot-footer__top{display:grid;grid-template-columns:1fr auto 1fr;gap:30px;align-items:center;padding:46px 0}.foot-footer__newsletter form{display:flex}.foot-footer__newsletter input{min-width:0;flex:1;padding:13px;border:0}.foot-footer__newsletter button{border:0;padding:0 15px;background:var(--nt-gold);color:#fff}.foot-footer__brand{text-align:center}.foot-footer__social{text-align:right}.foot-footer__social div{display:flex;justify-content:end;gap:8px}.foot-footer__social a{display:grid;place-items:center;width:34px;height:34px;background:var(--nt-gold);color:#fff;text-decoration:none}.foot-footer__divider{height:1px;background:rgba(255,255,255,.16)}.foot-footer__grid{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:32px;padding:42px 0}.foot-footer h3{font:700 17px var(--nt-serif)}.foot-footer p,.foot-footer li{color:#c6c0b6;line-height:1.65;font-size:14px}.foot-footer ul{list-style:none;padding:0}.foot-footer a{color:inherit;text-decoration:none}.foot-footer__bottom{padding:18px;text-align:center;border-top:1px solid rgba(255,255,255,.1);color:#aaa397;font-size:12px}@media(max-width:800px){.nt-about__grid,.nt-testimonial{grid-template-columns:1fr;gap:36px}.nt-showcase__grid,.nt-service-grid,.nt-blog__grid{grid-template-columns:1fr 1fr}.nt-showcase__grid .nt-hours{grid-column:span 2}.nt-rail{grid-auto-columns:75%}.nt-testimonial__media{min-height:340px}.foot-footer__grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.nt-container{width:min(100% - 30px,1280px)}.foot-header__masthead-inner{padding:0 15px}.foot-navigation-wrap{padding:0 15px 10px}.foot-mobile-toggle{display:block;width:100%;padding:11px;border:1px solid #ddd;background:#fff;color:var(--nt-dark)}.foot-navigation{display:none;flex-direction:column;align-items:stretch}.foot-navigation.is-open{display:flex}.foot-navigation a{padding:10px}.nt-hero__slide,.nt-hero__content{min-height:540px}.nt-hero__content{padding:0 24px}.nt-hero__content h1{font-size:42px}.nt-section{padding:64px 0}.nt-about__media img{height:360px}.nt-about__media span{left:12px;top:15px}.nt-showcase__grid,.nt-service-grid,.nt-blog__grid{grid-template-columns:1fr}.nt-showcase__grid .nt-hours{grid-column:auto}.nt-section-head--row{display:block}.nt-testimonial__copy{padding:55px 25px}.nt-stats .nt-container>div{grid-template-columns:1fr;gap:30px}.foot-footer__top,.foot-footer__grid{grid-template-columns:1fr;text-align:center}.foot-footer__social div{justify-content:center}.foot-footer__newsletter form{max-width:340px;margin:auto}}
